/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import json
assets={('/' if p=='index.html' else '/'+p):Path(p).read_text() for p in ['index.html','src/styles.css','src/main.js','src/data.js']}
script='const assets = '+json.dumps(assets)+';\\n'
script+='''const page = await browser.getPage(\"gpt6-mail\");
await page.setViewportSize({ width: 1440, height: 900 });
await page.route(\"http://localhost:9180/**\", async route => {
  const path = route.request().url().replace(\"http://localhost:9180\", \"\").split(\"?\")[0] || \"/\";
  const body = assets[path];
  if (body === undefined) return route.fulfill({ status: 404, body: \"Not found\" });
  const type = path.endsWith(\".css\") ? \"text/css\" : path.endsWith(\".js\") ? \"text/javascript\" : \"text/html\";
  return route.fulfill({ status: 200, contentType: type, body });
});
await page.goto(\"http://localhost:9180/\", { waitUntil: \"domcontentloaded\" });
console.log(\"title\", await page.title());
console.log(\"initial\", await page.locator(\".mail-row\").count(), await page.locator(\".category-tabs button\").count());
await page.locator('[data-action=\"open\"][data-id=\"t1\"]').click();
console.log(\"thread\", await page.locator(\".message-card\").count(), await page.locator(\".thread-heading h1\").textContent());
await page.locator('[data-action=\"reply\"]').first().click();
await page.locator('[data-field=\"body\"]').fill(\"Thanks for the thoughtful notes.\");
await page.locator('[data-action=\"send\"]').click();
console.log(\"sent\", await page.locator(\".toast\").textContent());
await page.locator('[data-action=\"compose\"]').click();
await page.locator('[data-field=\"to\"]').fill(\"jordan@example.com\");
await page.locator('[data-field=\"subject\"]').fill(\"Browser flow test\");
await page.locator('[data-field=\"body\"]').fill(\"Hello from the browser.\");
await page.locator('[data-action=\"send\"]').click();
await page.locator('[data-action=\"navigate\"][data-view=\"Sent\"]').click();
console.log(\"sent-row\", await page.locator('.mail-row:has-text(\"Browser flow test\")').count());
await page.setViewportSize({ width: 390, height: 844 });
console.log(\"mobile\", await page.evaluate(() => ({w:document.documentElement.scrollWidth, viewport:innerWidth, menu:getComputedStyle(document.querySelector('.menu-trigger')).display})));
'''
Path('scripts/browser-check.js').write_text(script)
PY"

